mapper.select:
WITH clock AS ( SELECT 28800 + TIMESTAMPDIFF(SECOND, NOW(), UTC_TIMESTAMP()) AS to_beijing ), per_type AS ( SELECT DATE(TIMESTAMPADD(SECOND, clock.to_beijing, s.created_at)) AS submission_date, COUNT(*) AS algo_count, 0 AS db_count FROM submission s
INNER JOIN question q ON q.id = s.question_id AND q.created_by = #{ownerId}
CROSS JOIN clock WHERE s.created_at >= TIMESTAMPADD(SECOND, -clock.to_beijing, #{from}) AND s.created_at < TIMESTAMPADD(SECOND, -clock.to_beijing, #{until}) GROUP BY submission_date UNION ALL SELECT DATE(TIMESTAMPADD(SECOND, clock.to_beijing, s.created_at)) AS submission_date, 0, COUNT(*) FROM db_submission s
INNER JOIN db_question q ON q.id = s.question_id AND q.created_by = #{ownerId}
CROSS JOIN clock WHERE s.created_at >= TIMESTAMPADD(SECOND, -clock.to_beijing, #{from}) AND s.created_at < TIMESTAMPADD(SECOND, -clock.to_beijing, #{until}) GROUP BY submission_date ) SELECT submission_date AS date, SUM(algo_count) AS algo_count, SUM(db_count) AS db_count FROM per_type GROUP BY submission_date
